        color=next(v for row in block for v in row if v not in (0,sepcolor) and v!=1)
        bands.append((prev,s,color)); prev=s+1
    # find the special shape: cells of a color that is not any band color... demo shape color = 5 = sep? no, sep=8, shape=5
    colors=[c for _,_,c in bands]
